export function renderMatrix(options) {
  const text = renderMatrixText(options);
  // Relative links must keep pointing at checked-in files after renames.
  for (const [, link] of text.matchAll(/\]\(([^)\s]+)\)/g)) {
    if (/^[a-z]+:/i.test(link) || link.startsWith('#')) continue;
    assert.ok(existsSync(resolve(root, link.split('#')[0])), `TEST_MATRIX.md links to missing ${link}`);
  }
  return text;
}
